package com.sumedha.commerce.product.entity; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="product_attributes") public class ProductAttribute{@Id @Column(name="attribute_id") private UUID id;@Column(name="product_id") private UUID productId;@Column(name="attribute_name") private String name;@Column(name="attribute_value") private String value;@Column(name="created_at") private Instant createdAt;protected ProductAttribute(){}public ProductAttribute(UUID p,String n,String v){id=UUID.randomUUID();productId=p;name=n;value=v;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getProductId(){return productId;}public String getName(){return name;}public String getValue(){return value;}public Instant getCreatedAt(){return createdAt;}}
